-- Additional OMS workflow examples. Safe to re-run: existing rows are never updated.
BEGIN;
DO $$
BEGIN
  IF current_database() <> 'oms_test'
     OR NOT EXISTS (SELECT 1 FROM provider WHERE id='5eed0a00-0000-4000-8000-000000000001' AND "providerName"='Demo Provider')
     OR NOT EXISTS (SELECT 1 FROM provider WHERE id='5eed0b00-0000-4000-8000-000000000001' AND "providerName"='Synthetic Isolation Provider') THEN
    RAISE EXCEPTION 'Refusing workflow seed outside the expected synthetic OMS database';
  END IF;
  IF EXISTS (
    SELECT 1 FROM work_order
    WHERE provider_id='5eed0a00-0000-4000-8000-000000000001'
      AND "workOrderNumber" BETWEEN '910001' AND '910010'
      AND id NOT BETWEEN '5eed0c00-0000-4000-8000-000000000001' AND '5eed0c00-0000-4000-8000-000000000010'
  ) THEN RAISE EXCEPTION 'Workflow work-order numbers are already used by non-fixture rows'; END IF;
  IF EXISTS (
    SELECT 1 FROM work_order
    WHERE id BETWEEN '5eed0c00-0000-4000-8000-000000000001' AND '5eed0c00-0000-4000-8000-000000000010'
      AND (provider_id IS DISTINCT FROM '5eed0a00-0000-4000-8000-000000000001'
        OR "workOrderNumber" IS DISTINCT FROM ('9100' || right(id, 2)))
  ) THEN RAISE EXCEPTION 'Workflow fixture work-order IDs conflict with existing data'; END IF;
  IF EXISTS (SELECT 1 FROM task WHERE id BETWEEN '5eed0c00-0000-4000-8000-000000000021' AND '5eed0c00-0000-4000-8000-000000000030' AND provider_id IS DISTINCT FROM '5eed0a00-0000-4000-8000-000000000001')
    OR EXISTS (SELECT 1 FROM line_item WHERE id BETWEEN '5eed0c00-0000-4000-8000-000000000041' AND '5eed0c00-0000-4000-8000-000000000049' AND provider_id IS DISTINCT FROM '5eed0a00-0000-4000-8000-000000000001')
    OR EXISTS (SELECT 1 FROM follow_up WHERE id BETWEEN '5eed0c00-0000-4000-8000-000000000061' AND '5eed0c00-0000-4000-8000-000000000063' AND provider_id IS DISTINCT FROM '5eed0a00-0000-4000-8000-000000000001')
    OR EXISTS (SELECT 1 FROM part_request WHERE id BETWEEN '5eed0c00-0000-4000-8000-000000000071' AND '5eed0c00-0000-4000-8000-000000000072' AND provider_id IS DISTINCT FROM '5eed0a00-0000-4000-8000-000000000001')
    OR EXISTS (SELECT 1 FROM "order" WHERE id='5eed0c00-0000-4000-8000-000000000051' AND provider_id IS DISTINCT FROM '5eed0a00-0000-4000-8000-000000000001')
  THEN RAISE EXCEPTION 'Workflow detail fixture IDs conflict with existing data'; END IF;
END $$;

